import {precisionInputAttributes} from './number-display.js';
import {annualTextHTML} from './annual-localization.js';
import {isYearlyMarginPath,MAX_NEAR_TERM_YEARS} from './margin-path.js';
// Hosts take the yearly helpers with the view that draws them.
export {isYearlyMarginPath,YEARLY_MARGIN_PATH_VERSION,MAX_NEAR_TERM_YEARS} from './margin-path.js';
// Presentation only: values come from each model's actual annual rows.
const finite=Number.isFinite;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Shared "set each year" editor: the first years are typed (or dragged) one by
// one; a stepper changes how many; the last field is when the long-run value is
// reached. Values and the count are ordinary inputs owned by the host view.
// Focus shows this text, not 0.328 × 100 = 32.800000000000004; an unedited
// field still reads back the exact stored value.
const cleanText=(v,scale)=>finite(v)?String(Number((v*scale).toPrecision(12))):undefined;
export function yearlyPathFieldsHTML(prefix,kind,{values=[],scale=1,legend,firstYear=1,maxYears=MAX_NEAR_TERM_YEARS,terminalYear,terminalLabel,terminalControl,describedBy='',linked=null}={}){
 const count=values.length+firstYear-1,cell=(label,id,attrs,input)=>`<div class="yearly-path-cell${attrs.includes('data-linked')?' is-linked':''}"><label for="${id}">${label}</label>${input}</div>`;
 const cells=[...(linked?[cell('Year 1',`${prefix}-${kind}-year-1`,'data-linked',`<input id="${prefix}-${kind}-year-1" data-${kind}-year="1" data-yearly-prefix="${prefix}" data-linked="${esc(linked.field)}" data-scale="${scale}" type="text" inputmode="decimal" ${precisionInputAttributes(linked.value,scale,cleanText(linked.value,scale))} aria-describedby="${prefix}-${kind}-year-1-note ${describedBy}"><small id="${prefix}-${kind}-year-1-note">${esc(linked.note)}</small>`)]:[]),
  ...values.map((v,i)=>{const year=i+firstYear,id=`${prefix}-${kind}-year-${year}`;return cell(`Year ${year}`,id,'',`<input id="${id}" data-${kind}-year="${year}" data-yearly-prefix="${prefix}" data-scale="${scale}" type="text" inputmode="decimal" ${precisionInputAttributes(v,scale,cleanText(v,scale))} aria-describedby="${describedBy}">`);})].join('');
 return `<fieldset class="yearly-path" data-yearly-path="${kind}"><legend>${esc(legend)}</legend><div class="yearly-path-head"><div class="yearly-path-count"><label for="${prefix}-${kind}-nearTermYears">Years you set</label><div class="yearly-path-stepper"><button type="button" class="quiet" data-yearly-step="-1" data-yearly-kind="${kind}" aria-label="Set one fewer year" ${count<=1?'disabled':''}>−</button><input id="${prefix}-${kind}-nearTermYears" data-yearly-count="${kind}" data-yearly-prefix="${prefix}" type="text" inputmode="numeric" value="${count}" aria-describedby="${describedBy}"><button type="button" class="quiet" data-yearly-step="1" data-yearly-kind="${kind}" aria-label="Set one more year" ${count>=maxYears?'disabled':''}>+</button></div></div><div class="yearly-path-terminal"><label for="${prefix}-${kind}-terminalYear">${esc(terminalLabel)}</label><input id="${prefix}-${kind}-terminalYear" ${terminalControl} type="text" inputmode="numeric" ${precisionInputAttributes(terminalYear,1)} aria-describedby="${describedBy}"></div></div><div class="yearly-path-grid">${cells}</div></fieldset>`;
}
export function marginPhaseControlsHTML(prefix,p,{terminalMargin,terminalInput=true,source='',annual=false,yearlyOption=false}={}){
 const yearly=yearlyOption&&p?.enabled===true&&isYearlyMarginPath(p),phased=p?.enabled===true&&!yearly;
 if(yearly)return `<section class="margin-phase-controls" aria-label="Optional margin phases" data-path-mode="yearly"><label for="${prefix}-margin-mode">Margin path</label><select id="${prefix}-margin-mode" aria-describedby="${prefix}-margin-help"><option value="existing">Simple transition</option><option value="phased">Interim target and fade</option><option value="yearly" selected>Set each year</option></select><p id="${prefix}-margin-help" class="micro">Set the margin for each of the first years yourself. After your last year it moves in a straight line to the mature margin above, then holds.</p>${yearlyPathFieldsHTML(prefix,'margin',{values:p.nearTermMargins,scale:100,legend:'Your operating margin for each year · %',terminalYear:p.terminalYear,terminalLabel:'Mature margin reached in year',terminalControl:`data-margin-control="terminalYear" data-margin-prefix="${prefix}" data-scale="1"`,describedBy:`${prefix}-margin-method`})}<p class="micro" id="${prefix}-margin-method"><span>Example: 18% in year 1, 22% in year 2, 25% in year 3, then the mature margin by year 8.</span> <span>In simulation, one mature-margin draw moves every year you set by the same amount.</span> ${annualTextHTML(source)}</p><p class="micro" id="${prefix}-margin-status" role="status"></p></section>`;
 const fields=[['interimMargin','Interim operating margin · %',100],['interimYear','Interim margin reached in year',1],['declineStartYear','Margin decline begins in year',1],['terminalYear','Terminal margin reached in year',1],...(terminalInput?[['terminalMargin','Terminal operating margin · %',100]]:[])];
 return `<section class="margin-phase-controls" aria-label="Optional margin phases"${yearlyOption?` data-path-mode="${phased?'phased':'existing'}"`:''}><label for="${prefix}-margin-mode">Margin path</label><select id="${prefix}-margin-mode" aria-describedby="${prefix}-margin-help"><option value="existing" ${p?.enabled?'':'selected'}>${annual?'Manual yearly margins':'Simple transition'}</option><option value="phased" ${phased?'selected':''}>Interim target and fade</option>${yearlyOption?'<option value="yearly">Set each year</option>':''}</select><p id="${prefix}-margin-help" class="micro">${p?.enabled?'Rise or fall to an interim margin, hold it, then fade to the terminal margin. Each year is independent of the revenue-growth horizon.':annual?'Optional. Manual yearly margins keeps the current explicit annual margins, including any generated rows.':'Optional. Simple transition changes the curve using your current operating profile and terminal margin; saved phase inputs stay available.'}</p>${p?.enabled?`<div class="margin-phase-grid">${fields.map(([key,label,scale])=>`<label for="${prefix}-margin-${key}">${label}<input id="${prefix}-margin-${key}" data-margin-control="${key}" data-margin-prefix="${prefix}" data-scale="${scale}" type="text" inputmode="${scale===100?'decimal':'numeric'}" ${annual?'data-precision-grammar="annual"':''} ${precisionInputAttributes(key==='terminalMargin'?terminalMargin:p[key],scale,p.inputText?.[key])} aria-describedby="${prefix}-margin-method"></label>`).join('')}</div><p class="micro" id="${prefix}-margin-method"><span>Example: reach 30% in year 3, hold through year 5, fade to 20% in year 10, then hold 20%.</span> ${terminalInput?'':'<span>The mature operating margin above is the terminal target.</span> '}${annual?'<span>Applying phase controls replaces individual margin overrides.</span> ':''}${annualTextHTML(source)}</p>`:''}<p class="micro" id="${prefix}-margin-status" role="status"></p></section>`;
}
export function marginPathChartHTML(points,{id='margin-path-chart',source=''}={}){
 if(!points?.length||points.some(p=>!finite(p.margin)))return '<p class="micro">Complete valid margin assumptions to see the full margin path.</p>';
 const lo=Math.min(0,...points.map(p=>p.margin)),hi=Math.max(.05,...points.map(p=>p.margin)),span=hi-lo||.05,last=Math.max(1,points.at(-1).year),x=p=>58+p.year/last*550,y=v=>160-(v-lo)/span*125,fmt=v=>(v*100).toLocaleString('en-US',{maximumFractionDigits:2})+'%';
 return `<section class="margin-path-visual"><h3>Operating margin through the forecast</h3><svg class="margin-path-chart" viewBox="0 0 640 205" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">Full operating-margin path</title><desc id="${id}-desc">${esc(points.map(p=>`Year ${p.year}: ${fmt(p.margin)}`).join('; '))}. ${esc(source)}</desc>${[lo,(lo+hi)/2,hi].map(v=>`<line x1="58" x2="608" y1="${y(v)}" y2="${y(v)}" stroke="currentColor" opacity=".16"/><text x="50" y="${y(v)+4}" text-anchor="end" font-size="12" fill="currentColor">${fmt(v)}</text>`).join('')}<path d="${points.map((p,i)=>(i?'L':'M')+x(p)+','+y(p.margin)).join(' ')}" fill="none" stroke="currentColor" stroke-width="3"/>${points.map(p=>`<circle cx="${x(p)}" cy="${y(p.margin)}" r="2" fill="currentColor"><title>Year ${p.year}: ${fmt(p.margin)}</title></circle>`).join('')}${[points[0],points[Math.floor((points.length-1)/2)],points.at(-1)].map(p=>`<text x="${x(p)}" y="185" text-anchor="middle" font-size="12" fill="currentColor">Year ${p.year}</text>`).join('')}</svg><p class="micro"><span>Actual modeled EBIT ÷ revenue.</span> ${annualTextHTML(source)} <span>Final margin holds after its selected year unless an annual row is manually overridden.</span></p></section>`;
}
